import { lazy, Suspense, useState } from 'react';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { inView, listNotebooks } from '@/db/repo.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import styles from './NotebookChip.module.css';

/**
 * Fetched when the chip is first tapped. The sheet brings the new-notebook
 * form, the language picker and the paywall with it, and Today, which shows
 * this chip, should not wait for any of them to paint.
 */
const NotebookSheet = lazy(() =>
  import('./NotebookSheet.js').then((module) => ({ default: module.NotebookSheet })),
);

/**
 * Which notebook you are looking at, and the way to another one.
 *
 * It renders nothing at all while there is one notebook, which is almost
 * always. A name with a chevron beside it promises somewhere to go, and
 * with nothing to switch to that promise is a small lie; the way to a
 * second notebook lives in Settings, where somebody goes looking for it.
 *
 * Once there are two it appears on Today and on the notebook itself,
 * because those are the screens where being on the wrong one is confusing
 * and Settings is three taps away.
 *
 * It reads the view rather than the active notebook, so with everything in
 * view it says so. Showing one notebook's name while the screen below it
 * holds every word is the one thing this control must not do.
 */
export function NotebookChip({
  tone = 'page',
  className,
}: {
  /**
   * Where it is sitting. `hero` is the dark strip at the top of Today,
   * where the page tint would be invisible and the text unreadable.
   */
  tone?: 'page' | 'hero';
  className?: string | undefined;
} = {}): React.JSX.Element | null {
  // Both: inView lists only what is showing, which is one notebook unless
  // everything is in view, so it cannot answer whether there is a second.
  const notebooks = useLiveQuery(() => listNotebooks(), undefined, []);
  const view = useLiveQuery(() => inView(), undefined, []);
  const [open, setOpen] = useState(false);

  if (notebooks === undefined || notebooks.length < 2 || view === undefined) return null;
  const name = view.all ? t('notebooks.all') : (view.showing?.title ?? '');
  if (name === '') return null;

  return (
    <>
      <button
        type="button"
        className={cx(styles.chip, tone === 'hero' && styles.onHero, className)}
        aria-label={`${t('notebooks.open')}: ${name}`}
        onClick={() => {
          setOpen(true);
        }}
      >
        <Icon name="notebook" size={15} weight={1.9} className={styles.mark} />
        <span className={styles.name} dir="auto">
          {name}
        </span>
        <Icon name="chevronDown" size={14} weight={2.2} className={styles.go} />
      </button>
      {open && (
        <Suspense fallback={null}>
          <NotebookSheet
            activeId={view.showing?.id}
            onClose={() => {
              setOpen(false);
            }}
          />
        </Suspense>
      )}
    </>
  );
}
